#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Edge {
    int u, v;
};

int main() {
    // Otimização de I/O para programação competitiva
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<int>> by_sum(2 * n + 1);
    vector<Edge> edges;
    edges.reserve(2 * m);

    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        int s = u + v;

        by_sum[s].push_back(edges.size());
        edges.push_back({u, v});

        by_sum[s].push_back(edges.size());
        edges.push_back({v, u});
    }

    vector<int> best(n + 1, 1);
    vector<int> ans(n + 1, 1);
    vector<int> dp(edges.size(), 0);

    for (int s = 2 * n; s >= 2; --s) {
        if (by_sum[s].empty()) continue;

        // Fase 1: Calcular dp para todas as arestas com soma s
        for (int idx : by_sum[s]) {
            int v = edges[idx].v;
            dp[idx] = 1 + best[v];
        }

        // Fase 2: Atualizar o valor de best para os vértices de origem
        for (int idx : by_sum[s]) {
            int u = edges[idx].u;
            if (dp[idx] > best[u]) {
                best[u] = dp[idx];
            }
            if (dp[idx] > ans[u]) {
                ans[u] = dp[idx];
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        cout << ans[i] << (i == n ? "" : " ");
    }
    cout << "\n";

    return 0;
}
